const crypto = require('node:crypto');
const express = require('express');
const session = require('express-session');
const { rateLimit } = require('express-rate-limit');
const argon2 = require('argon2');

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET is required');

const app = express();
app.use(express.json({ limit: '10kb' }));

app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    maxAge: 2 * 60 * 60 * 1000,
  },
}));

// username -> { id, username, passwordHash }. Replace with a database.
const users = new Map();

// Verified against when the username is unknown, so response time does not
// reveal which usernames exist.
const dummyHash = argon2.hash(crypto.randomBytes(16).toString('hex'));

// Only failed attempts (status >= 400) count toward the limit.
const failedLoginLimiter = (options) => rateLimit({
  windowMs: 15 * 60 * 1000,
  skipSuccessfulRequests: true,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many failed attempts. Try again later.' },
  ...options,
});

const ipLimiter = failedLoginLimiter({ limit: 20 });
const accountLimiter = failedLoginLimiter({
  limit: 5,
  keyGenerator: (req) => `user:${req.body.username.toLowerCase()}`,
});

function requireCredentials(req, res, next) {
  const { username, password } = req.body ?? {};
  const valid = typeof username === 'string' && typeof password === 'string'
    && username.length > 0 && username.length <= 64
    && password.length > 0 && password.length <= 256;
  if (!valid) return res.status(400).json({ error: 'username and password are required' });
  next();
}

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not logged in' });
  next();
}

app.post('/register', requireCredentials, async (req, res, next) => {
  try {
    const username = req.body.username.toLowerCase();
    if (req.body.password.length < 8) {
      return res.status(400).json({ error: 'Password must be at least 8 characters' });
    }
    const passwordHash = await argon2.hash(req.body.password); // argon2id, salted
    if (users.has(username)) return res.status(409).json({ error: 'Username taken' });
    users.set(username, { id: crypto.randomUUID(), username, passwordHash });
    res.status(201).json({ ok: true });
  } catch (err) {
    next(err);
  }
});

app.post('/login', ipLimiter, requireCredentials, accountLimiter, async (req, res, next) => {
  try {
    const user = users.get(req.body.username.toLowerCase());
    const hash = user ? user.passwordHash : await dummyHash;
    const passwordOk = await argon2.verify(hash, req.body.password);
    if (!user || !passwordOk) {
      return res.status(401).json({ error: 'Invalid username or password' });
    }
    // New session ID on login prevents session fixation.
    req.session.regenerate((err) => {
      if (err) return next(err);
      req.session.userId = user.id;
      res.json({ ok: true });
    });
  } catch (err) {
    next(err);
  }
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.json({ ok: true });
  });
});

app.get('/me', requireAuth, (req, res) => {
  res.json({ userId: req.session.userId });
});

const port = process.env.PORT || 3000;
app.listen(port, () => console.log(`Listening on ${port}`));

